    d19_easy = [
        ("KV Cache Foundations", "Cơ chế 'KV Cache' (Key-Value Caching) trong suy luận LLM được sử dụng để làm gì?",
         ["Lưu trữ lịch sử chat của người dùng trên đĩa cứng", "Lưu trữ lại các vector Key và Value của các token đã xử lý trước đó trong bộ nhớ VRAM, giúp mô hình không phải tính toán lại Attention cho toàn bộ chuỗi token cũ khi sinh mỗi token mới", "Tự động dịch văn bản sang tiếng Anh", "Tăng kích thước font chữ"], 1,
         "KV Cache là kỹ thuật tối ưu hóa sống còn của giải mã tự hồi quy (Autoregressive Generation), giảm độ phức tạp tính toán từ $O(N^2)$ xuống $O(N)$ cho mỗi token mới.", "Day 19 - Slide: KV Cache Foundations"),
        ("PagedAttention in vLLM", "Thuật toán 'PagedAttention' trong thư viện vLLM lấy cảm hứng từ nguyên lý nào của Hệ điều hành máy tính?",
         ["Lấy cảm hứng từ thùng rác Recycle Bin", "Lấy cảm hứng từ Bộ nhớ Ảo và Phân trang (Virtual Memory & Paging): Chia nhỏ KV Cache thành các khối trang vật lý (Blocks/Pages) không liên tục trong VRAM, loại bỏ hoàn toàn hiện tượng phân mảnh bộ nhớ", "Lấy cảm hứng từ trình duyệt web", "Lấy cảm hứng từ chuột máy tính"], 1,
         "PagedAttention quản lý bộ nhớ KV Cache linh hoạt như cách hệ điều hành quản lý RAM, giảm lãng phí bộ nhớ từ 60-80% xuống dưới 4%.", "Day 19 - Slide: PagedAttention & vLLM Architecture"),
        ("Continuous Batching vs Static Batching", "Kỹ thuật 'Continuous Batching' (hay In-flight Batching) vượt trội hơn 'Static Batching' truyền thống ở điểm nào?",
         ["Continuous batching chỉ phục vụ được 1 người", "Continuous Batching thực hiện gom nhóm ở cấp độ từng bước lặp (Iteration-level): Cho phép các request mới tham gia vào batch ngay lập tức và giải phóng các request đã hoàn thành sớm mà không phải chờ đợi các câu trả lời dài khác", "Static batching chạy nhanh hơn 100 lần", "Không có sự khác biệt nào"], 1,
         "Continuous Batching loại bỏ thời gian chết do sự chênh lệch độ dài câu trả lời, tăng thông lượng phục vụ của GPU lên gấp 2-4 lần.", "Day 19 - Slide: Continuous vs Static Batching"),
        ("Speculative Decoding", "Nguyên lý hoạt động của 'Speculative Decoding' (Giải mã suy đoán) là gì?",
         ["Đoán mò kết quả bằng hàm random", "Sử dụng một Mô hình Nhỏ siêu tốc (Draft Model) để sinh trước một chuỗi $K$ token phỏng đoán trong vài mili-giây, sau đó dùng Mô hình Lớn (Target Model) để thẩm định và chấp nhận song song các token đúng trong đúng 1 bước", "Chạy mô hình vào ban đêm", "Bắt người dùng tự viết trước câu trả lời"], 1,
         "Speculative Decoding biến quá trình sinh tuần tự chậm chạp thành thẩm định song song tốc độ cao mà hoàn toàn không làm suy giảm chất lượng đầu ra.", "Day 19 - Slide: Speculative Decoding Mechanics"),
        ("Quantization Methods: AWQ & GPTQ", "AWQ (Activation-aware Weight Quantization) và GPTQ là các thuật toán phục vụ mục đích gì?",
         ["Tăng độ phân giải hình ảnh", "Lượng tử hóa trọng số mô hình sau huấn luyện (Post-Training Quantization) xuống 4-bit (INT4) với độ suy giảm chất lượng cực thấp, giúp giảm 70% dung lượng VRAM và tăng tốc độ suy luận", "Chơi game trực tuyến", "Quản lý cơ sở dữ liệu"], 1,
         "AWQ và GPTQ là các giải pháp chuẩn công nghiệp giúp nén mô hình LLM xuống 4-bit mà vẫn duy trì năng lực suy luận sắc bén.", "Day 19 - Slide: 4-bit Weight Quantization: AWQ vs GPTQ"),
        ("GGUF Format & llama.cpp", "Định dạng tệp tin `GGUF` và thư viện `llama.cpp` nổi tiếng vì khả năng gì?",
         ["Chỉnh sửa video 4K", "Cho phép chạy suy luận các mô hình LLM được lượng tử hóa cực kỳ mượt mà và tối ưu trực tiếp trên CPU và máy tính cá nhân (Apple Silicon / x86) mà không cần GPU đắt tiền", "Tự động viết email quảng cáo", "Làm mát máy tính"], 1,
         "`llama.cpp` và định dạng GGUF đã dân chủ hóa việc chạy LLM cục bộ trên các phần cứng tiêu dùng thông thường với hiệu năng đáng kinh ngạc.", "Day 19 - Slide: GGUF Format & Local CPU Inference with llama.cpp"),
        ("Inference Engines: TensorRT-LLM", "Thư viện TensorRT-LLM được phát triển bởi tổ chức nào nhằm tối ưu hóa suy luận trên GPU NVIDIA?",
         ["NVIDIA", "Google", "Mozilla", "Wikipedia"], 0,
         "TensorRT-LLM là bộ công cụ tối ưu hóa suy luận độc quyền hiệu năng cao nhất của NVIDIA, khai thác tối đa phần cứng Tensor Cores và FlashAttention.", "Day 19 - Slide: NVIDIA TensorRT-LLM Framework"),
        ("Inference Engines: TGI", "TGI (Text Generation Inference) là công cụ máy chủ phục vụ suy luận mã nguồn mở được phát triển bởi tổ chức nào?",
         ["Hugging Face", "Apple", "Oracle", "Spotify"], 0,
         "TGI do Hugging Face phát triển là một trong những giải pháp chuẩn mực đầu tiên triển khai Continuous Batching, PagedAttention và FlashAttention cho cộng đồng.", "Day 19 - Slide: Hugging Face Text Generation Inference (TGI)"),
        ("Triton Inference Server", "NVIDIA Triton Inference Server mang lại ưu thế gì cho các hệ sinh thái AI doanh nghiệp?",
         ["Chỉ hỗ trợ duy nhất 1 mô hình Python", "Hỗ trợ phục vụ đồng thời nhiều mô hình đa khung (PyTorch, ONNX, TensorRT, vLLM), Quản lý hàng đợi request động, Cân bằng tải đa GPU và hỗ trợ gRPC/HTTP chuẩn mực", "Tự động tắt máy chủ khi có tải", "Chỉ chạy được trên điện thoại"], 1,
         "Triton Inference Server là nền tảng phục vụ mô hình toàn diện cấp doanh nghiệp, hỗ trợ đa mô hình và tối ưu hóa tài nguyên phần cứng tập trung.", "Day 19 - Slide: NVIDIA Triton Inference Server Overview"),
        ("TTFT vs Inter-Token Latency (ITL)", "Hai chỉ số đo lường độ trễ cốt lõi trong suy luận LLM là gì?",
         ["Thời gian bật máy và thời gian tắt máy", "Time to First Token (TTFT - Thời gian từ khi gửi prompt đến khi nhận được token đầu tiên) và Inter-Token Latency (ITL / Time per Output Token - Thời gian sinh ra mỗi token tiếp theo)", "Số lượng ký tự và số lượng dòng", "Tốc độ chuột và tốc độ gõ phím"], 1,
         "TTFT đo lường tốc độ phản hồi ban đầu (Prefill latency); ITL đo lường độ mượt mà của dòng chữ hiển thị (Generation latency).", "Day 19 - Slide: Inference Latency Metrics: TTFT & ITL"),
        ("Prefix Caching (Prompt Caching)", "Tính năng 'Prefix Caching' trong vLLM và các API hiện đại mang lại lợi ích gì khi người dùng liên tục hỏi đáp trên cùng một tài liệu dài?",
         ["Tự động xóa tài liệu sau 1 phút", "Lưu trữ lại trạng thái KV Cache của đoạn văn bản mở đầu (System Prompt hoặc RAG Context dài); các câu hỏi tiếp theo có cùng đoạn mở đầu sẽ tái sử dụng ngay KV Cache này, giảm 90% TTFT và chi phí", "Tăng giá tiền API lên gấp đôi", "Bắt người dùng nhập lại tài liệu từ đầu"], 1,
         "Prefix Caching loại bỏ việc tính toán lại Attention cho các đoạn prompt cố định lặp lại, tăng tốc độ phản hồi tức thì cho các ứng dụng nhiều lượt hội thoại.", "Day 19 - Slide: Prompt & Prefix Caching in Serving"),
        ("FlashAttention Versions (v1, v2, v3)", "Sự phát triển từ FlashAttention-1 đến FlashAttention-3 tập trung vào cải tiến điều gì?",
         ["Tăng kích thước file cài đặt", "Tối ưu hóa sâu hơn việc phân chia công việc trên các Warp của GPU, Giảm thiểu các thao tác đồng bộ không cần thiết và Tận dụng tối đa phần cứng FP8 Tensor Cores trên kiến trúc Hopper", "Thêm các hình ảnh động vào code", "Chuyển sang chạy trên CPU"], 1,
         "FlashAttention-3 đẩy hiệu năng tính toán Attention đạt gần 75% công suất đỉnh lý thuyết của chip H100 thông qua tối ưu hóa vi kiến trúc Hopper.", "Day 19 - Slide: Evolution of FlashAttention (v1 to v3)"),
        ("Model Offloading for Inference", "Khi sử dụng thư viện `accelerate` để 'Offload' một phần mô hình sang RAM hoặc SSD, điều gì xảy ra với tốc độ suy luận?",
         ["Tốc độ suy luận tăng nhanh gấp 100 lần", "Mô hình có thể chạy được trên GPU dung lượng nhỏ nhưng tốc độ suy luận sẽ bị chậm đi đáng kể do độ trễ truyền dữ liệu liên tục qua bus PCIe", "Mô hình tự động sinh ra kết quả sai", "GPU sẽ tự động tắt nguồn"], 1,
         "Model Offloading giúp giải quyết bài toán thiếu VRAM để chạy được mô hình nhưng phải đánh đổi bằng tốc độ sinh token chậm hơn nhiều.", "Day 19 - Slide: Model Offloading Trade-offs"),
        ("Dynamic Temperature & Top-p Sampling", "Hai siêu tham số `temperature` và `top_p` trong quá trình suy luận (Decoding) điều khiển khía cạnh nào của câu trả lời?",
         ["Điều khiển tốc độ quạt và độ sáng màn hình", "Điều khiển Độ ngẫu nhiên và Tính sáng tạo: `temperature` làm phẳng hoặc làm nhọn phân phối xác suất; `top_p` (Nucleus Sampling) giới hạn việc lấy mẫu trong tập hợp các token có tổng xác suất tích lũy $\\le p$", "Điều khiển dung lượng RAM tiêu thụ", "Điều khiển số lượng dòng code Python"], 1,
         "Temperature và Top-p là các công cụ toán học định hình phân phối xác suất token, quyết định mức độ sáng tạo hay tất định của câu trả lời.", "Day 19 - Slide: Sampling Hyperparameters: Temperature & Top-p"),
        ("Greedy vs Beam Search Decoding", "Sự khác biệt giữa 'Greedy Decoding' và 'Beam Search' trong giải mã ngôn ngữ là gì?",
         ["Greedy decoding tốn nhiều bộ nhớ hơn 100 lần", "Greedy Decoding luôn chọn token có xác suất cao nhất tại mỗi bước (nhanh, đơn giản); Beam Search duy trì đồng thời $K$ chuỗi giả thuyết tiềm năng nhất (chất lượng cao hơn nhưng tốn nhiều bộ nhớ và thời gian tính toán)", "Beam search chỉ dùng cho hình ảnh", "Cả 2 đều cho kết quả giống hệt nhau 100%"], 1,
         "Greedy Search nhanh và tiết kiệm tài nguyên, là chuẩn mặc định cho LLM; Beam Search duy trì nhiều nhánh tìm kiếm, thường dùng cho dịch thuật chuyên sâu.", "Day 19 - Slide: Decoding Algorithms: Greedy vs Beam Search")
    ]

    d19_med = [
        ("KV Cache Memory Footprint Equation", "Công thức toán học tính toán dung lượng bộ nhớ VRAM tiêu tốn cho KV Cache của 1 token trên một mô hình Transformer chuẩn là gì?",
         ["$2 \\times \\text{layers}$ bytes", "$\\text{KV\\_Size\\_per\\_token} = 2 \\times 2 \\times n_{\\text{layers}} \\times n_{\\text{heads\\_kv}} \\times d_{\\text{head}}$ bytes (với 2 cho Key và Value, 2 cho độ chính xác FP16)", "Luôn cố định 1MB cho mọi mô hình", "Không phụ thuộc vào số lượng tầng của mô hình"], 1,
         "Dung lượng KV Cache tăng tuyến tính theo số tầng, số đầu Attention của KV, kích thước đầu và độ dài chuỗi token, trở thành gánh nặng bộ nhớ lớn nhất khi phục vụ đồng thời nhiều người dùng.", "Day 19 - Slide: Mathematical Formulation of KV Cache Memory"),
        ("Multi-Query Attention (MQA) & Grouped-Query Attention (GQA)", "Kiến trúc GQA (Grouped-Query Attention như trong Llama-3/Mistral) giảm dung lượng KV Cache như thế nào so với MHA (Multi-Head Attention)?",
         ["Xóa toàn bộ các Query Heads", "Gom nhóm nhiều Query Heads (ví dụ: 8 Query Heads) cùng chia sẻ chung 1 Key Head và 1 Value Head duy nhất, giúp giảm kích thước KV Cache tới 87.5% trong khi duy trì năng lực biểu diễn tương đương MHA", "Chỉ giữ lại đúng 1 Attention Head cho toàn bộ mô hình", "Tăng kích thước KV Cache lên gấp đôi"], 1,
         "GQA là bước tiến kiến trúc mang tính cách mạng, giảm thiểu đáng kể chi phí bộ nhớ KV Cache và tăng tốc độ suy luận vượt bậc cho các mô hình thế hệ mới.", "Day 19 - Slide: Multi-Query (MQA) and Grouped-Query Attention (GQA)"),
        ("Chunked Prefill Architecture in vLLM", "Tính năng 'Chunked Prefill' trong các serving engine hiện đại giải quyết sự cạnh tranh tài nguyên giữa giai đoạn Prefill và Generation như thế nào?",
         ["Tắt hoàn toàn giai đoạn Prefill", "Chia nhỏ các prompt đầu vào dài thành các khối Chunk (ví dụ: 512 tokens/chunk) và đồng lên lịch thực thi song song các Chunks này cùng với các token Generation trong cùng một bước lặp, triệt tiêu hiện tượng tăng vọt độ trễ Inter-Token Latency (ITL Spikes)", "Bắt người dùng phải chờ 10 phút", "Chỉ xử lý các prompt ngắn hơn 10 chữ"], 1,
         "Chunked Prefill làm phẳng đường cong tải tính toán của GPU, duy trì độ trễ sinh token mượt mà ngay cả khi có các prompt dài hàng nghìn token liên tục nạp vào.", "Day 19 - Slide: Chunked Prefill & Latency Smoothing"),
        ("Speculative Decoding: Acceptance Rate & Speedup", "Tốc độ tăng tốc thực tế (Effective Speedup $\\alpha$) của Speculative Decoding phụ thuộc vào những yếu tố toán học nào?",
         ["Phụ thuộc vào màu sắc của máy chủ", "Tỉ lệ chấp nhận của Mô hình Đích (Acceptance Rate $\\beta \\in [0, 1]$), Số lượng token phỏng đoán $K$, và Tỉ số chi phí tính toán giữa Mô hình Nhỏ và Mô hình Lớn (Cost Ratio $\\frac{C_{\\text{draft}}}{C_{\\text{target}}}$)", "Phụ thuộc vào nhiệt độ phòng máy", "Luôn cố định tăng tốc đúng 10 lần"], 1,
         "Hiệu quả tăng tốc của Speculative Decoding đạt cực đại khi mô hình Draft có độ tương đồng ngữ nghĩa cao với mô hình Target và có chi phí suy luận siêu nhẹ.", "Day 19 - Slide: Speculative Decoding Mathematics & Speedup Laws"),
        ("Weight-Only vs Weight-and-Activation Quantization", "Sự khác biệt căn bản giữa 'Weight-Only Quantization' (W4A16 / W8A16) và 'Weight-and-Activation Quantization' (W8A8 / W4A4) là gì?",
         ["Không có sự khác biệt nào", "Weight-Only chỉ nén trọng số mô hình trên bộ nhớ VRAM và giải nén sang FP16 khi tính toán (tối ưu cho Memory-Bound Generation); Weight-and-Activation nén cả trọng số và ma trận kích hoạt, cho phép thực hiện tính toán số nguyên INT8/INT4 trực tiếp trên Tensor Cores (tối ưu cả Compute-Bound Prefill)", "Weight-Only chỉ dùng cho CPU", "W8A8 làm mất toàn bộ dữ liệu"], 1,
         "W8A8/W4A4 mở khóa sức mạnh tính toán số nguyên thuần túy trên phần cứng, trong khi W4A16 tập trung giải phóng băng thông bộ nhớ.", "Day 19 - Slide: Weight-Only vs Full Quantization Regimes"),
        ("Outlier Features in LLM Quantization", "Hiện tượng 'Outlier Activations' (Các giá trị kích hoạt đột biến khổng lồ xuất hiện ở một số chiều nhất định) gây khó khăn gì cho việc lượng tử hóa INT8 và giải pháp của SmoothQuant là gì?",
         ["Làm máy tính bị tắt nguồn", "Các giá trị ngoại lai làm dải động bị kéo dãn khiến hầu hết các giá trị thông thường bị mất độ mịn khi làm tròn; SmoothQuant giải quyết bằng cách áp dụng phép biến đổi toán học tương đương nhân chuyển dịch độ khó từ Activations sang Weights trước khi lượng tử", "Xóa toàn bộ các giá trị ngoại lai về 0", "Không thể lượng tử hóa được mô hình lớn"], 1,
         "SmoothQuant làm phẳng các đột biến kích hoạt bằng cách chia tỷ lệ cân bằng giữa ma trận kích hoạt và ma trận trọng số, bảo toàn độ chính xác khi nén W8A8.", "Day 19 - Slide: Outlier Activations & SmoothQuant Architecture"),
        ("vLLM Distributed Serving: Tensor Parallelism vs Pipeline Parallelism", "Khi triển khai một mô hình 70B trên 4 GPU để phục vụ suy luận trực tuyến (Online Serving), tại sao Tensor Parallelism ($TP=4$) luôn được ưu tiên hơn Pipeline Parallelism ($PP=4$)?",
         ["Vì Tensor Parallelism không tốn VRAM", "Tensor Parallelism chia đều việc tính toán cho cả 4 GPU trong từng token sinh ra (giảm 4 lần độ trễ Inter-Token Latency); Pipeline Parallelism sinh token theo dây chuyền tuần tự làm tăng độ trễ đơn luồng lên gấp 4 lần và xuất hiện bế tắc đường ống", "Vì Pipeline Parallelism cấm dùng cho suy luận", "Không có sự khác biệt nào về độ trễ"], 1,
         "Tensor Parallelism tận dụng tối đa sức mạnh song song hóa của cụm GPU để giảm thiểu độ trễ sinh từng token cho từng người dùng đơn lẻ.", "Day 19 - Slide: Parallelism Strategies for Low-Latency Serving"),
        ("Disaggregated Prefill and Decoding Architecture", "Kiến trúc 'Tách rời Prefill và Decoding' (Disaggregated Serving / Splitwise Architecture) phân chia tài nguyên phần cứng như thế nào?",
         ["Tất cả các máy chủ đều làm chung một việc", "Tách riêng cụm máy chủ: 'Prefill Nodes' (Chuyên xử lý các prompt dài với GPU có sức mạnh tính toán FP8 Tensor Cores cực mạnh) và 'Decoding Nodes' (Chuyên sinh token với GPU có băng thông bộ nhớ HBM3 tối đa), truyền KV Cache qua mạng RDMA siêu tốc", "Chạy Prefill trên điện thoại và Decoding trên máy tính", "Tắt bớt các máy chủ vào ban đêm"], 1,
         "Tách biệt hoàn toàn phần cứng tối ưu cho tính toán (Compute-heavy Prefill) và phần cứng tối ưu cho băng thông (Memory-heavy Decoding) loại bỏ sự can thiệp lẫn nhau và tối ưu hóa 100% tài nguyên.", "Day 19 - Slide: Disaggregated Prefill-Decoding Architecture"),
        ("Medusa Architecture for Speculative Decoding", "Kiến trúc 'Medusa' (Multiple Decoding Heads) cải tiến Speculative Decoding mà không cần mô hình Draft riêng biệt bằng cách nào?",
         ["Vẽ hình con rắn nhiều đầu", "Gắn thêm nhiều 'Decoding Heads' nhỏ trực tiếp lên tầng cuối cùng của chính mô hình gốc, cho phép mô hình tự sinh đồng thời nhiều token tương lai ($t+1, t+2, t+3$) song song trong cùng 1 bước Forward Pass", "Chạy 10 mô hình cùng lúc", "Xóa tầng Attention cuối cùng"], 1,
         "Medusa loại bỏ sự phức tạp của việc duy trì và nạp 2 mô hình độc lập, tích hợp các đầu dự báo tương lai trực tiếp vào thân mô hình mẹ.", "Day 19 - Slide: Medusa: Multi-Head Speculative Decoding"),
        ("KV Cache Compression & Eviction Policies", "Khi cuộc hội thoại vượt quá dung lượng KV Cache tối đa, các thuật toán Eviction (như StreamingLLM hoặc H2O - Heavy Hitter Oracle) loại bỏ token nào?",
         ["Xóa toàn bộ lịch sử trò chuyện", "StreamingLLM giữ lại các 'Attention Sinks' (4 token đầu tiên của chuỗi) kết hợp một Cửa sổ Trượt (Sliding Window các token gần nhất); H2O giữ lại các token có điểm tích lũy Attention cao nhất trong lịch sử", "Xóa ngẫu nhiên các token", "Chỉ giữ lại đúng 1 token duy nhất"], 1,
         "Attention Sinks và Heavy Hitters bảo toàn các neo chú ý quan trọng nhất, cho phép mô hình duy trì ngữ cảnh dài vô hạn mà không bị sụp đổ logic.", "Day 19 - Slide: KV Cache Eviction: StreamingLLM & H2O"),
        ("Dynamic Request Batching with Max Batch Size Limits", "Trong Triton Inference Server, tham số `max_queue_delay_microseconds` (ví dụ: 5000µs) cân bằng giữa Thông lượng và Độ trễ như thế nào?",
         ["Bắt server phải chờ 5 tiếng", "Quy định thời gian tối đa mà server được phép gom thêm các request mới vào batch: Nếu batch đạt kích thước tối đa HOẶC hết thời gian chờ 5ms, server lập tức đẩy batch vào GPU để xử lý, đảm bảo SLA độ trễ phản hồi", "Tự động hủy bỏ các request bị trễ", "Tắt toàn bộ hệ thống"], 1,
         "`max_queue_delay` điều tiết khoảng đệm gom tải linh hoạt, tối đa hóa kích thước batch trong giờ cao điểm trong khi duy trì độ trễ thấp lúc vắng khách.", "Day 19 - Slide: Dynamic Batching & Queue Latency Trade-offs"),
        ("Triton Ensemble Models & BLS", "Tính năng 'Ensemble Models' và Business Logic Scripting (BLS) trong NVIDIA Triton cho phép làm gì?",
         ["Soạn thảo văn bản", "Nối ghép nhiều mô hình khác nhau thành một chuỗi Pipeline duy nhất (ví dụ: Tokenizer C++ -> TensorRT LLM Engine -> Output Post-processor Python) thực thi trong bộ nhớ chia sẻ với độ trễ cực thấp", "In báo cáo tài chính", "Chơi game 3D"], 1,
         "Triton BLS và Ensembles cho phép xây dựng các pipeline AI phức tạp gồm nhiều bước tiền/hậu xử lý mà không tốn chi phí truyền dữ liệu qua mạng giữa các bước.", "Day 19 - Slide: Triton Ensemble Models & Business Logic Scripting"),
        ("FlashDecoding / FlashDecoding++", "Thuật toán FlashDecoding tăng tốc độ sinh token cho các chuỗi ngữ cảnh siêu dài (Long-Context Generation) bằng cách nào?",
         ["Xóa bớt 90% số token trong context", "Song song hóa phép tính Attention dọc theo chiều dài của KV Cache (Parallelizing over the Sequence Dimension): Chia nhỏ KV Cache thành nhiều phần và phân bổ cho các GPU Thread Blocks tính toán song song, sau đó gom cụm bằng Reduction", "Chuyển code sang chạy trên CPU", "Tắt toàn bộ cơ chế Attention"], 1,
         "FlashDecoding phá vỡ giới hạn tuần tự của Attention trong bước sinh token, tận dụng triệt để hàng nghìn lõi GPU ngay cả khi Batch Size = 1 trên ngữ cảnh dài.", "Day 19 - Slide: FlashDecoding for Long-Context Generation"),
        ("Context Caching Token Economics", "Khi sử dụng API có hỗ trợ Prompt Caching (như Anthropic Claude hoặc OpenAI), mức chiết khấu giá (Cost Discount) cho các Token được đọc từ Cache thường ở mức nào?",
         ["Không được giảm giá", "Được giảm từ 50% đến 90% chi phí so với giá token đầu vào thông thường (Prompt Tokens), đồng thời giảm mạnh độ trễ TTFT", "Được miễn phí và được tặng thêm tiền", "Bị tính phí gấp 10 lần"], 1,
         "Prompt Caching mang lại lợi thế kinh tế khổng lồ cho các ứng dụng có tiền tố prompt dài và lặp lại nhiều lần như RAG và Code Assistant.", "Day 19 - Slide: Token Economics of Prompt Caching"),
        ("Quantization-Aware Training (QAT) vs PTQ", "Tại sao Lượng tử hóa trong Huấn luyện (Quantization-Aware Training - QAT) lại đạt độ chính xác cao hơn Lượng tử hóa sau Huấn luyện (Post-Training Quantization - PTQ) ở mức 2-bit hoặc 4-bit?",
         ["Vì QAT không dùng toán học", "QAT mô phỏng sai số lượng tử hóa (Fake Quantization) trực tiếp trong quá trình huấn luyện, cho phép các trọng số mô hình tự động thích nghi và bù trừ sai số làm tròn thông qua lan truyền ngược", "Vì PTQ bị cấm sử dụng", "Không có sự khác biệt nào"], 1,
         "QAT rèn luyện mô hình làm quen với độ chính xác thấp ngay từ giai đoạn học tập, duy trì chất lượng vượt trội ở các mức nén cực hạn (INT2/INT4).", "Day 19 - Slide: QAT vs PTQ Mechanics"),
        ("Serving Concurrency vs Memory Saturation", "Điều gì xảy ra khi số lượng người dùng đồng thời vượt quá dung lượng VRAM cấp phát cho KV Cache trong vLLM?",
         ["Máy chủ bị nổ", "vLLM tự động kích hoạt cơ chế Preemption (Tạm dừng một số request có độ ưu tiên thấp và đẩy tạm KV Cache của chúng sang RAM CPU) hoặc xếp hàng đợi, bảo vệ hệ thống không bị sập OOM", "Tự động xóa vĩnh viễn tài khoản người dùng", "Chuyển toàn bộ câu trả lời thành chuỗi rỗng"], 1,
         "Cơ chế Preemption và Request Scheduling thông minh của vLLM đảm bảo hệ thống vận hành bền bỉ dưới tải cực hạn mà không bao giờ bị sập bộ nhớ.", "Day 19 - Slide: Preemption & Scheduling in vLLM"),
        ("Model Compilation: torch.compile & Inductor", "Công cụ `torch.compile(model, mode='max-autotune')` trong PyTorch 2.x tăng tốc độ suy luận bằng cách nào?",
         ["Biến code Python thành file HTML", "Phân tích đồ thị tính toán (FX Graph) và tự động sinh mã máy C++/Triton Kernels tối ưu: Tự động gom cụm các phép toán liên tiếp (Kernel Fusion), loại bỏ hoàn toàn việc phân bổ bộ nhớ trung gian thừa thãi", "Xóa toàn bộ các layer phức tạp", "Chỉ chạy được trên máy tính của Meta"], 1,
         "`torch.compile` biến đổi mã nguồn Python linh hoạt thành các kernel mã máy tối ưu hóa cao độ, tận dụng tối đa năng lực phần cứng.", "Day 19 - Slide: PyTorch 2.x torch.compile & Kernel Fusion"),
        ("Inference Profiling with NVIDIA Nsight Systems", "Khi phân tích hiệu năng phục vụ suy luận LLM bằng NVIDIA Nsight Systems, chỉ số nào cho biết GPU đang bị bỏ đói dữ liệu?",
         ["Số lượng ký tự trong file code", "Tỉ lệ phần trăm thời gian GPU nhàn rỗi (GPU Idle Time / Tensor Core Inactivity) và khoảng cách thời gian giữa các kernel tính toán liên tiếp trên CUDA Stream", "Nhiệt độ phòng máy", "Màu sắc của giao diện"], 1,
         "Nsight Systems vạch trần các khoảng thời gian lãng phí giữa các kernel, giúp kỹ sư phát hiện hiện tượng CPU overhead hoặc nghẽn I/O.", "Day 19 - Slide: Inference Profiling with Nsight Systems")
    ]

    d19_hard = [
        ("Hyperscale Real-Time AI Inference Architecture with Sub-50ms SLA", "Thiết kế một Bản quy hoạch Kiến trúc Phục vụ Suy luận Đa Mô hình Siêu quy mô (Hyperscale Inference Cluster Architecture) xử lý 500,000 QPS với cam kết p99 TTFT < 50ms và Thông lượng > 10,000 tokens/giây trên toàn cầu. Trình bày chi tiết cấu trúc phân tầng tối ưu từ Edge Ingress đến GPU Serving Engines?",
         ["Sử dụng 1 máy chủ FastAPI đơn luồng chạy trên laptop", "Triển khai Kiến trúc Phục vụ Phân tầng Đa Cấp độ: 1. Global Anycast Edge Router với Semantic Prompt Cache (Cloudflare/Upstash, tỷ lệ Cache Hit 45%); 2. Disaggregated Serving Cluster: Tách biệt Prefill Nodes (Cụm H100 chạy FP8 Transformer Engine) và Decoding Nodes (Cụm L40S/H200 chạy TensorRT-LLM với Continuous Batching); 3. Chunked Prefill (512 tokens/chunk) kết hợp Speculative Decoding (EAGLE-2 Tree-based Draft Models tăng tốc 3.2x); 4. vLLM PagedAttention v2 với Prefix Caching tự động; 5. Triton Inference Server quản lý Dynamic Batching (queue timeout 2ms) và Dynamic Tensor Parallelism qua NVLink Fabric", "Tắt toàn bộ hệ thống cache và chạy mô hình nguyên bản FP32", "Chỉ cho phép 1 người dùng truy cập tại một thời điểm"], 1,
         "Kiến trúc phục vụ siêu quy mô kết hợp giữa tách rời Prefill-Decode, suy đoán cấu trúc cây EAGLE, nén bộ nhớ đệm phân trang và định tuyến biên mang lại hiệu năng đỉnh cao với chi phí tối ưu nhất thế giới.", "Day 19 - Slide: Hyperscale LLM Inference Architecture Master Blueprint"),
        ("Mathematical Optimization of Speculative Tree Decoding (EAGLE-2)", "Chứng minh toán học và phân tích cấu trúc cây xác suất (Speculative Tree Construction & Dynamic Drafting) trong EAGLE-2 giúp nâng cao Tỉ lệ Chấp nhận Token (Token Acceptance Rate) từ 60% lên > 85%?",
         ["EAGLE-2 chỉ dùng đoán mò ngẫu nhiên", "EAGLE-2 mở rộng không gian phỏng đoán từ một chuỗi tuyến tính đơn lẻ $1 \\times K$ thành một Cây Giả thuyết Đa nhánh (Speculative Tree Graph): Dựa trên phân phối xác suất có điều kiện $P(t_{i+1} | t_i, h_t)$ từ tầng kích hoạt ẩn, xây dựng cây Top-$M$ nhánh tiềm năng nhất; Target Model chỉ cần đúng 1 lần Forward Pass với Tree Attention Mask để thẩm định đồng thời toàn bộ các đường dẫn trong cây, tối đa hóa số token được chấp nhận trung bình trên mỗi bước $\\mathbb{E}[\\text{Tokens/step}] > 3.5$", "EAGLE-2 làm tăng độ trễ lên gấp 10 lần", "Không có công thức toán học nào"], 1,
         "Mô hình hóa cây suy đoán kết hợp Tree Attention Mask cho phép thẩm định song song nhiều kịch bản tương lai trong một lần suy luận duy nhất, phá vỡ giới hạn của giải mã tuyến tính.", "Day 19 - Slide: Mathematical Formulation of Speculative Tree Decoding"),
        ("Micro-Architectural Triton Kernel Fusion for High-Performance Attention", "Thiết kế một Custom Triton GPU Kernel thực hiện kết hợp nguyên tử (Fused Kernel) cho cụm phép toán: `RMSNorm -> QKV GEMM -> Rotary Position Embedding (RoPE) -> PagedAttention` trong đúng 1 lần nạp dữ liệu vào SRAM?",
         ["Viết 4 hàm Python riêng biệt và gọi tuần tự", "Xây dựng Triton Fused Block Kernel: Nạp ma trận kích hoạt từ HBM vào SRAM một lần duy nhất -> Thực hiện tính toán RMSNorm trong thanh ghi -> Nhân ma trận QKV bằng Tensor Cores -> Áp dụng phép quay RoPE trực tiếp trên thanh ghi -> Thực hiện FlashAttention Tiling và ghi kết quả cuối cùng ra VRAM, triệt tiêu 100% chi phí đọc/ghi 3 ma trận trung gian ra HBM và giảm 60% độ trễ Prefill", "Chuyển toàn bộ code sang chạy trên CPU", "Tắt tính năng RoPE"], 1,
         "Kernel Fusion ở cấp độ thanh ghi vi kiến trúc chip triệt tiêu hoàn toàn sự tiêu tốn băng thông bộ nhớ của các bước trung gian, đẩy hiệu năng tính toán tiệm cận giới hạn vật lý của GPU.", "Day 19 - Slide: Custom Triton Fused Kernels for Transformer Layers"),
        ("Sub-Millisecond Dynamic Model Swapping over PCIe Bus", "Một máy chủ GPU cần phục vụ linh hoạt 10 mô hình LoRA thích ứng chuyên ngành khác nhau cho hàng nghìn khách hàng. Thiết kế Kiến trúc Phục vụ Đa LoRA Tức thời (Multi-LoRA Dynamic Serving Engine) nào đạt độ trễ chuyển đổi < 1ms?",
         ["Mỗi khi có request mới thì tắt máy chủ và nạp lại mô hình từ đầu tốn 5 phút", "Triển khai S-LoRA / Punica Batched Multi-LoRA Serving Engine: Nạp duy nhất 1 Mô hình Gốc (Base Model) cố định trong VRAM; Toàn bộ các trọng số LoRA Adapters nhỏ (vài chục MB) được lưu trong RAM CPU và nạp động vào VRAM qua DMA không khóa; Sử dụng Custom CUDA Segmented GEMM Kernel cho phép xử lý một Batch chứa đồng thời 50 requests thuộc 10 LoRA adapters khác nhau trong cùng một bước tính toán", "Cấm người dùng sử dụng LoRA", "Chạy 10 máy chủ GPU riêng biệt cho 10 LoRA gây lãng phí hàng triệu USD"], 1,
         "Segmented Batched GEMM cho phép một instance GPU duy nhất phục vụ đồng thời hàng chục bộ LoRA khác nhau trong cùng một mẻ tính toán mà không tốn chi phí hoán đổi mô hình.", "Day 19 - Slide: S-LoRA & Batched Multi-Adapter Serving Architecture"),
        ("Zero-Downtime Hot KV-Cache Migration across Degraded GPU Nodes", "Khi một GPU đang phục vụ một phiên hội thoại dài 100,000 tokens (KV Cache dung lượng 8GB) có dấu hiệu sắp hỏng phần cứng, quy trình Di trú Nóng Bộ nhớ Đệm (Zero-Downtime Hot KV-Cache Migration) sang GPU khỏe mạnh diễn ra như thế nào?",
         ["Ngắt kết nối của người dùng và bắt họ gõ lại từ đầu", "Quy trình Di trú Không Gián đoạn qua GPUDirect RDMA: 1. Bộ điều phối cấp phát không gian trang mới trên GPU đích; 2. Thiết lập kênh truyền RDMA trực tiếp giữa VRAM của GPU nguồn và GPU đích; 3. Đồng bộ hóa 8GB KV Cache qua mạng InfiniBand trong 20ms trên luồng nền; 4. Chuyển hướng bảng trang (Page Table Remapping) của session sang GPU mới ngay giữa 2 token liên tiếp mà người dùng không hề cảm nhận thấy sự chậm trễ", "Khởi động lại toàn bộ trung tâm dữ liệu", "Tắt toàn bộ hệ thống"], 1,
         "Hot KV-Cache Migration qua RDMA bảo vệ các phiên làm việc quan trọng của người dùng không bị gián đoạn ngay cả khi phần cứng GPU bên dưới gặp sự cố vật lý.", "Day 19 - Slide: Zero-Downtime KV Cache RDMA Migration"),
        ("Dynamic Micro-Batch Sizing under Variable Token Generation Lengths", "Khi phục vụ lưu lượng truy cập hỗn hợp với câu trả lời ngắn 10 tokens và câu trả lời dài 4,000 tokens, thuật toán Tối ưu hóa Lô Động (Reinforcement-Learning Adaptive Batch Scheduler) điều tiết dung lượng mẻ tính toán như thế nào?",
         ["Cố định Batch Size = 1 vĩnh viễn", "Sử dụng Thuật toán Điều phối Nhận thức Ngân sách Bộ nhớ Động (Memory-Aware Continuous Scheduler with Predictive Generation Lengths): Sử dụng mô hình nhẹ dự báo độ dài câu trả lời của từng request -> Tự động co giãn kích thước Batch Size sau mỗi chu kỳ xung nhịp sao cho tổng dung lượng KV Cache dự kiến tiệm cận chính xác 98% VRAM khả dụng mà không bao giờ vượt ngưỡng gây OOM", "Để server tự động sập khi quá tải", "Từ chối toàn bộ các câu hỏi dài"], 1,
         "Bộ điều phối thích ứng dự báo nhu cầu bộ nhớ theo thời gian thực tối đa hóa mật độ khai thác GPU trong khi loại bỏ hoàn toàn rủi ro tràn bộ nhớ.", "Day 19 - Slide: Predictive Memory-Aware Dynamic Batch Scheduling"),
        ("FP8 Weight-and-Activation Quantization with Outlier Preservation", "Khi thực hiện lượng tử hóa toàn diện FP8 (E4M3 cho trọng số và E5M2 cho gradient/kích hoạt) trên kiến trúc Transformer khổng lồ, kỹ thuật Cô lập Chiều Ngoại lai (Outlier Dimension Isolation & Mixed-Precision Gemm) bảo vệ độ chính xác bằng cách nào?",
         ["Bỏ qua các chiều ngoại lai", "Phân tách ma trận tính toán thành 2 phần: 99.9% các chiều thông thường được nhân bằng FP8 Tensor Cores tốc độ cao; 0.1% các chiều ngoại lai nhạy cảm (Outlier Channels) được giữ nguyên ở định dạng BF16 và nhân trên một luồng tính toán song song chính xác cao, sau đó cộng tổng kết quả, triệt tiêu 100% sự suy thoái năng lực ngôn ngữ", "Chuyển toàn bộ mô hình về FP32", "Làm tròn tất cả các số về 0"], 1,
         "Mixed-Precision FP8 Gemm kết hợp cô lập ngoại lai mang lại tốc độ gấp đôi của phần cứng số thực 8-bit trong khi duy trì độ chính xác hoàn hảo tương đương mô hình gốc.", "Day 19 - Slide: Mixed-Precision FP8 GEMM with Outlier Channel Isolation"),
        ("Streaming Speculative Decoding with Lookahead Parallel Verification", "Trong các ứng dụng Stream phản hồi giọng nói thời gian thực (Real-Time Voice AI với SLA < 100ms), làm thế nào để kết hợp Speculative Decoding với Giao thức Truyền Dòng Âm thanh SSE?",
         ["Chờ sinh xong toàn bộ câu rồi mới phát âm thanh", "Triển khai Bộ đệm Luồng Suy đoán Bất đồng bộ (Asynchronous Speculative SSE Streaming Engine): Ngay khi Mô hình Đích chấp nhận một cụm 3 token đúng, các token này được phát ngay lập tức vào Bộ giải mã Âm thanh (Audio TTS Engine) qua luồng Stream song song trong khi GPU tiếp tục suy đoán cụm token tiếp theo, nén độ trễ từ văn bản đến giọng nói (Text-to-Audio Latency) xuống < 40ms", "Bắt người dùng phải đọc văn bản thay vì nghe âm thanh", "Tắt toàn bộ hệ thống suy đoán"], 1,
         "Kết hợp giải mã suy đoán và phát luồng âm thanh gối đầu tức thời mang lại trải nghiệm hội thoại thời gian thực mượt mà như người thật.", "Day 19 - Slide: Sub-50ms Real-Time Voice Streaming Pipelines"),
        ("Cross-Node Disaggregated Attention with RDMA Prefetching", "Khi triển khai kiến trúc Tách rời Prefill-Decode trên mạng phân tán, làm thế nào để truyền KV Cache dung lượng 10GB từ Prefill Node sang Decoding Node mà không làm tăng TTFT của người dùng?",
         ["Lưu 10GB ra file rồi gửi qua email", "Áp dụng Kỹ thuật Truyền Dòng RDMA Phân đoạn Song song (Pipelined Paged KV-Streaming over InfiniBand): Ngay khi Prefill Node hoàn thành tính toán Attention cho Block 0 của prompt, dữ liệu Block 0 lập tức được bắn qua RDMA sang VRAM của Decoding Node trong khi Prefill Node tiếp tục tính toán Block 1, che giấu hoàn toàn 100% thời gian truyền mạng", "Bắt Decoding Node phải tự tính toán lại từ đầu", "Tắt tính năng tách rời"], 1,
         "Truyền dữ liệu KV Cache phân đoạn gối đầu qua RDMA triệt tiêu độ trễ mạng chuyển giao, hiện thực hóa kiến trúc Disaggregated Serving với hiệu năng đỉnh cao.", "Day 19 - Slide: Pipelined Paged KV-Streaming over RDMA Fabrics"),
        ("Quantization Error Minimization with Fisher Information Matrix", "Thuật toán GPTQ sử dụng Ma trận Thông tin Fisher (Hessian Matrix $H = 2 X X^T$) để cực tiểu hóa sai số lượng tử hóa như thế nào?",
         ["Tính trung bình cộng các số", "Mô hình hóa bài toán nén trọng số dưới dạng Bài toán Cực tiểu hóa Sai số Toàn phương bậc hai (Second-Order Error Minimization): Sử dụng nghịch đảo của ma trận Hessian $H^{-1}$ để xác định thứ tự lượng tử hóa tối ưu cho từng cột trọng số và tự động cập nhật bù trừ sai số tức thời cho tất cả các trọng số chưa lượng tử hóa còn lại trong ma trận", "Chọn ngẫu nhiên các trọng số để làm tròn", "Không sử dụng thông tin bậc hai"], 1,
         "Sử dụng thông tin đạo hàm bậc hai (Hessian/Fisher) cho phép GPTQ bù đắp sai số làm tròn một cách tối ưu toán học, duy trì chất lượng mô hình ở mức nén 4-bit và 3-bit.", "Day 19 - Slide: Mathematical Formulation of GPTQ Second-Order Error Optimization"),
        ("Dynamic Prefill Chunk Sizing under Heavy Network Jitter", "Trong môi trường đám mây có độ trễ mạng biến động mạnh, làm thế nào để thuật toán Chunked Prefill tự động điều chỉnh kích thước Chunk ($C_{\\text{chunk}}$) để vừa duy trì thông lượng vừa bảo vệ SLA của các luồng Generation?",
         ["Cố định kích thước chunk = 100", "Áp dụng Bộ Điều khiển Phản hồi Tỷ lệ - Tích phân (PID Controller on Inter-Token Latency): Liên tục đo lường thời gian thực thi của từng bước sinh token; nếu ITL vượt quá ngưỡng 25ms, bộ điều khiển tự động giảm kích thước Chunk Prefill xuống ($512 \\to 256 \\to 128$); khi ITL an toàn, tự động mở rộng Chunk lên 1,024 để tối đa hóa thông lượng Prefill", "Tắt tính năng chunking khi mạng bị chậm", "Không cần điều chỉnh"], 1,
         "Bộ điều khiển phản hồi PID tự động tìm điểm cân bằng động tối ưu giữa thông lượng nạp prompt và độ mượt mà của dòng token sinh ra.", "Day 19 - Slide: PID-Controlled Adaptive Chunk Sizing Engines"),
        ("Comprehensive LLM Serving Benchmark Framework (vLLM vs TGI vs TensorRT-LLM)", "Khi xây dựng một Khung Kiểm thử Tải và Đánh giá Năng lực Phục vụ Toàn diện (Serving Performance Benchmark Suite), ma trận đo đạc bắt buộc phải bao gồm những đồ thị tương quan nào?",
         ["Chỉ đo tốc độ tải trang web", "1. Đồ thị Đánh đổi Thông lượng vs Độ trễ (Throughput tokens/s vs p99 TTFT / ITL under Concurrency 1 to 1,000); 2. Đồ thị Khai thác VRAM và Tỉ lệ Phân mảnh KV Cache; 3. Đồ thị Phân phối Thời gian Xếp hàng (Queue Time Distribution); 4. Đường cong Suy giảm Hiệu năng dưới Áp lực Prompt Dài (Long-Context Stress Degradation Curve)", "Chỉ đo nhiệt độ máy chủ", "Đếm số lượng dòng code của các thư viện"], 1,
         "Ma trận kiểm chuẩn tải đa chiều cung cấp căn cứ kỹ thuật chính xác tuyệt đối để lựa chọn Serving Engine tối ưu cho từng bài toán nghiệp vụ doanh nghiệp.", "Day 19 - Slide: Comprehensive LLM Serving Benchmarking Methodology")
    ]
    add_day("Track 2: Infrastructure", "Day 19", "Inference Optimization & Serving Engines", d19_easy, d19_med, d19_hard)

    # ==========================================
    # DAY 20: Orchestration with Kubernetes & Slurm
    # ==========================================
    d20_easy = [
        ("Slurm Workload Manager", "Hệ thống Slurm (Simple Linux Utility for Resource Management) là gì trong các trung tâm dữ liệu AI và Siêu máy tính (HPC)?",
         ["Một phần mềm nghe nhạc", "Hệ thống quản lý cụm và điều phối hàng đợi tác vụ mã nguồn mở hàng đầu thế giới chuyên biệt cho các bài toán tính toán hiệu năng cao (HPC) và huấn luyện mô hình lớn", "Một loại card mạng", "Một ngôn ngữ lập trình mới"], 1,
         "Slurm là công cụ điều phối tiêu chuẩn vàng trong các siêu máy tính HPC, tối ưu hóa việc phân bổ tài nguyên GPU/CPU độc quyền cho các Job tính toán lớn.", "Day 20 - Slide: Slurm HPC Workload Manager Overview"),
        ("Slurm Commands: sbatch, srun, squeue", "Ba lệnh dòng lệnh cơ bản và phổ biến nhất trong Slurm là gì và công dụng của chúng?",
         ["`start`, `stop`, `delete`", "`sbatch` (Gửi một kịch bản Job chạy ngầm vào hàng đợi), `srun` (Chạy một tác vụ song song tương tác thời gian thực), và `squeue` (Xem danh sách các Jobs đang chạy hoặc đang chờ trong hàng đợi)", "`cpu`, `gpu`, `ram`", "`open`, `close`, `save`"], 1,
         "`sbatch`, `srun` và `squeue` là bộ ba công cụ điều khiển hàng ngày của mọi kỹ sư vận hành cụm siêu máy tính Slurm.", "Day 20 - Slide: Essential Slurm Commands"),
        ("Slurm Partitions", "Khái niệm 'Partition' trong Slurm tương đương với khái niệm nào?",
         ["Một phân vùng ổ đĩa cứng", "Một Hàng đợi Tác vụ (Job Queue) gom nhóm một tập hợp các máy chủ có đặc tính phần cứng tương đồng hoặc chính sách ưu tiên riêng (ví dụ: partition `gpu-h100`, partition `debug-short`)", "Một dòng code Python", "Một loại mật khẩu"], 1,
         "Partitions trong Slurm phân luồng các tác vụ theo loại tài nguyên phần cứng, thời gian chạy tối đa và mức độ ưu tiên của người dùng.", "Day 20 - Slide: Slurm Partitions and Quality of Service (QoS)"),
        ("Kubernetes for AI", "Tại sao Kubernetes (K8s) lại trở thành nền tảng điều phối phổ biến hàng đầu cho việc Triển khai và Phục vụ Mô hình AI (Inference Serving)?",
         ["Vì Kubernetes chỉ chạy được trên điện thoại", "Khả năng Tự động Co giãn (Auto-scaling), Tự phục hồi (Self-healing), Quản lý Microservices phân tán, Hệ sinh thái Cloud-Native khổng lồ và hỗ trợ Rolling Updates không downtime", "Vì Kubernetes không cần dùng máy chủ", "Vì Kubernetes được tạo ra bởi OpenAI"], 1,
         "Kubernetes là tiêu chuẩn vàng của kỷ nguyên Cloud-Native, xuất sắc trong việc quản lý vòng đời và co giãn các dịch vụ AI trực tuyến 24/7.", "Day 20 - Slide: Kubernetes in AI Infrastructure"),
        ("NVIDIA GPU Operator for Kubernetes", "NVIDIA GPU Operator tự động hóa những công việc phức tạp nào trên cụm Kubernetes?",
         ["Tự động mua thêm card đồ họa", "Tự động cài đặt và quản lý toàn bộ vòng đời của NVIDIA GPU Drivers, Container Toolkit, Kubernetes Device Plugin, và NVIDIA DCGM Exporter trên tất cả các Worker Nodes", "Tự động dịch mã nguồn Python sang C", "Tự động tắt nguồn máy tính"], 1,
         "GPU Operator chuẩn hóa và tự động hóa 100% quy trình thiết lập môi trường GPU phức tạp trên Kubernetes chỉ với 1 cú click.", "Day 20 - Slide: NVIDIA GPU Operator for Kubernetes"),
        ("K8s GPU Resource Allocation", "Trong Kubernetes Pod Spec, làm thế nào để yêu cầu cấp phát chính xác 2 GPU NVIDIA cho một container?",
         ["Khai báo `gpu: 2` trong biến môi trường", "Khai báo trong phần `resources`: `limits: { nvidia.com/gpu: 2 }` và `requests: { nvidia.com/gpu: 2 }`", "Ghi chú thích `# Cần 2 GPU` vào file YAML", "Gửi email cho ban quản trị cụm"], 1,
         "Kubernetes Device Plugin quy định tài nguyên GPU thông qua khóa `nvidia.com/gpu` trong trường limits và requests của container spec.", "Day 20 - Slide: GPU Resource Requests & Limits in K8s"),
        ("Kubernetes vs Slurm Decision", "Khi nào nên lựa chọn Slurm và khi nào nên lựa chọn Kubernetes cho hệ thống AI?",
         ["Slurm chỉ dùng cho game; Kubernetes chỉ dùng cho văn bản", "Lựa chọn Slurm cho các Tác vụ Huấn luyện Phân tán Lô lớn (Batch Large-Scale Training Jobs) đòi hỏi truy cập phần cứng bare-metal và mạng Infiniband tối đa; Lựa chọn Kubernetes cho các Dịch vụ Phục vụ Trực tuyến (Inference Serving, Web APIs, Microservices, CI/CD)", "Cả hai không thể dùng cho AI", "Luôn luôn bắt buộc phải dùng Slurm cho mọi việc"], 1,
         "Slurm thống trị mảng Batch HPC Training hiệu năng cực hạn; Kubernetes thống trị mảng Microservices, Data Pipelines và Online Model Serving.", "Day 20 - Slide: Kubernetes vs Slurm Decision Matrix"),
        ("Kueue in Kubernetes", "Công cụ 'Kueue' trong hệ sinh thái Kubernetes giải quyết bài toán gì cho AI Workloads?",
         ["Vẽ biểu đồ hình tròn", "Hệ thống Quản lý Hàng đợi Tác vụ Đa Người dùng (Multi-tenant Job Queueing System): Quản lý hạn ngạch tài nguyên (Resource Quotas), Hàng đợi ưu tiên (Fair Sharing) và Điều phối thời điểm chạy cho các Batch Jobs", "Tự động đổi tên Pods", "Tắt các container chạy chậm"], 1,
         "Kueue mang các tính năng quản lý hàng đợi và hạn ngạch công bằng tinh vi của HPC/Slurm lên nền tảng Kubernetes hiện đại.", "Day 20 - Slide: Job Queueing with Kubernetes Kueue"),
        ("Volcano Scheduler", "Bộ lập lịch 'Volcano' (CNCF Volcano Scheduler) trong Kubernetes được thiết kế chuyên biệt cho loại tác vụ nào?",
         ["Dự báo núi lửa phun trào", "Lập lịch nâng cao cho các Tác vụ Tính toán Hiệu năng cao (HPC, AI Training, Big Data) với các tính năng chuyên biệt như Gang Scheduling, Fair-share, và Task-topology awareness", "Quản lý website thương mại điện tử", "Chơi game trực tuyến"], 1,
         "Volcano bổ sung các thuật toán lập lịch nâng cao còn thiếu trong Kubernetes mặc định, tối ưu cho các bài toán phân tán quy mô lớn.", "Day 20 - Slide: CNCF Volcano Batch Scheduler"),
        ("Gang Scheduling Concept", "Khái niệm 'Gang Scheduling' (hay All-or-Nothing Scheduling) trong huấn luyện phân tán có nghĩa là gì?",
         ["Chỉ cho phép các nhóm xã hội đen chạy code", "Đảm bảo rằng TOÀN BỘ $N$ pods của một Job huấn luyện phân tán (ví dụ: 32 GPUs) BẮT BUỘC phải được cấp phát tài nguyên và khởi chạy CÙNG MỘT LÚC; nếu thiếu dù chỉ 1 pod thì KHÔNG khởi chạy bất kỳ pod nào", "Khởi chạy từng pod cách nhau 1 tiếng", "Tự động xóa các pod chạy chậm"], 1,
         "Gang Scheduling loại bỏ hiện tượng bế tắc tài nguyên (Deadlock) khi nhiều Job phân tán tranh chấp và chiếm giữ tài nguyên dở dang của nhau.", "Day 20 - Slide: Gang Scheduling (All-or-Nothing) Principles"),
        ("KubeRay (Ray on Kubernetes)", "KubeRay Operator mang lại lợi ích gì cho các kỹ sư AI?",
         ["Tự động vẽ đồ thị Ray-tracing", "Quản lý và tự động hóa toàn bộ vòng đời của các Cụm tính toán phân tán Ray (Ray Clusters) trên Kubernetes, phục vụ việc huấn luyện phân tán, tinh chỉnh mô hình và phục vụ suy luận (Ray Serve)", "Tăng tốc độ hiển thị hình ảnh", "Thay thế cho card mạng"], 1,
         "KubeRay tích hợp framework tính toán phân tán Ray mạnh mẽ vào hạ tầng Kubernetes một cách liền mạch và chuẩn Cloud-Native.", "Day 20 - Slide: KubeRay & Distributed AI Clusters"),
        ("Slurm `#SBATCH` Directives", "Các dòng lệnh bắt đầu bằng `#SBATCH` ở đầu một kịch bản Bash script phục vụ mục đích gì trong Slurm?",
         ["Là các dòng chú thích vô nghĩa", "Khai báo các tham số cấu hình tài nguyên cho Job (ví dụ: `--nodes=4`, `--gpus-per-node=8`, `--time=24:00:00`, `--partition=gpu`) được Slurm đọc và thực thi khi gửi lệnh `sbatch`", "Tự động xóa file sau khi chạy", "Đặt mật khẩu cho kịch bản"], 1,
         "Chỉ thị `#SBATCH` cho phép lập trình viên định nghĩa chính xác số lượng máy chủ, số GPU và giới hạn thời gian chạy cho tác vụ.", "Day 20 - Slide: Slurm Batch Script Directives"),
        ("Node Affinity and Taints/Tolerations", "Trong Kubernetes, cơ chế 'Taints & Tolerations' kết hợp 'Node Affinity' được dùng để làm gì đối với các máy chủ GPU đắt tiền?",
         ["Tự động khóa bàn phím", "Đảm bảo rằng CHỈ CÁC PODS CẦN GPU (có Toleration tương ứng) mới được phép lập lịch chạy trên các máy chủ GPU, ngăn chặn các Pods ứng dụng thông thường (như Nginx, Redis) chiếm dụng tài nguyên GPU quý giá", "Tăng tốc độ quạt tản nhiệt của node", "Xóa toàn bộ các container cũ"], 1,
         "Taints và Tolerations bảo vệ các nút phần cứng chuyên dụng (GPU/TPU) khỏi việc bị lãng phí bởi các tác vụ thông thường không yêu cầu tăng tốc phần cứng.", "Day 20 - Slide: K8s Taints, Tolerations & Node Affinity for GPUs"),
        ("DCGM Exporter for Prometheus", "NVIDIA DCGM Exporter (Data Center GPU Manager) xuất khẩu những số liệu giám sát nào vào Prometheus?",
         ["Xuất khẩu lịch sử duyệt web của lập trình viên", "Các số liệu phần cứng thời gian thực của GPU: GPU Utilization %, VRAM Usage %, Nhiệt độ GPU, Mức tiêu thụ điện năng (Watts), Tỉ lệ lỗi bộ nhớ ECC và Băng thông NVLink", "Xuất khẩu file mã nguồn Python", "Xuất khẩu danh sách nhân viên công ty"], 1,
         "DCGM Exporter là cầu nối cung cấp toàn bộ dữ liệu đo kiểm phần cứng GPU chi tiết cho hệ thống giám sát Prometheus và Grafana.", "Day 20 - Slide: GPU Metrics Monitoring with NVIDIA DCGM"),
        ("Slurm Environment Variables", "Trong một Job chạy bằng Slurm, biến môi trường `$SLURM_PROCID` biểu thị thông tin gì?",
         ["Giá tiền của máy chủ", "Chỉ số Rank định danh duy nhất (Global Process Rank từ 0 đến N-1) của tiến trình hiện tại trong toàn bộ cụm tác vụ phân tán", "Địa chỉ nhà của lập trình viên", "Số lượng dòng code trong chương trình"], 1,
         "`$SLURM_PROCID` được sử dụng trực tiếp để thiết lập biến `RANK` cho PyTorch Distributed trong các kịch bản huấn luyện tự động.", "Day 20 - Slide: Slurm Runtime Environment Variables")
    ]

    d20_med = [
        ("K8s Gang Scheduling Deadlock Scenario", "Nếu KHÔNG sử dụng Gang Scheduling, kịch bản bế tắc tài nguyên (Resource Deadlock) giữa Job A (cần 8 GPU) và Job B (cần 8 GPU) trên cụm chỉ có 12 GPU diễn ra như thế nào?",
         ["Cả hai Job đều hoàn thành trong 1 giây", "Bộ lập lịch mặc định cấp phát 6 GPU cho Job A và 6 GPU cho Job B; Cả hai Job đều không có đủ 8 GPU để bắt đầu chạy phân tán (DDP) nên cùng bị treo vĩnh viễn chờ đợi nhau nhả tài nguyên", "Máy chủ tự động tắt nguồn", "Toàn bộ GPU bị hỏng"], 1,
         "Thiếu Gang Scheduling dẫn đến bế tắc kinh điển: các Job phân tán chiếm giữ một phần tài nguyên và cùng chờ đợi tài nguyên của nhau không hồi kết.", "Day 20 - Slide: Distributed Deadlocks without Gang Scheduling"),
        ("Slurm Multi-Node PyTorch Script", "Trong một kịch bản Slurm `#SBATCH --nodes=4 --gpus-per-node=8`, lệnh nào sau đây khởi chạy huấn luyện PyTorch DDP chuẩn mực nhất trên toàn bộ 32 GPUs?",
         ["Chạy lệnh `python train.py` một lần duy nhất trên máy chủ đăng nhập", "`srun torchrun --nnodes=4 --nproc_per_node=8 --rdzv_backend=c10d --rdzv_endpoint=$MASTER_ADDR:$MASTER_PORT train.py`", "Gửi email chứa file train.py cho từng máy chủ", "Chạy 32 lần lệnh `python train.py` trong 32 cửa sổ terminal riêng lẻ"], 1,
         "`srun` kết hợp `torchrun` tự động phân phối tiến trình tới tất cả các nút máy chủ và thiết lập kết nối Rendezvous đồng bộ cho toàn bộ 32 GPU.", "Day 20 - Slide: Multi-Node Distributed Training with Slurm & Torchrun"),
        ("Kubernetes Topology-Aware Scheduling", "Tính năng 'Topology-Aware Scheduling' trong Volcano/Kubernetes tối ưu hóa việc phân bổ Pods trên các máy chủ như thế nào?",
         ["Phân bổ các Pods càng xa nhau càng tốt", "Ưu tiên gom nhóm các Pods thuộc cùng một Job huấn luyện vào các GPU nằm trên CÙNG MỘT MÁY CHỦ (Intra-node qua NVLink) hoặc CÙNG MỘT RACK SWITCH (Intra-rack), giảm thiểu độ trễ mạng liên rack", "Phân bổ ngẫu nhiên không theo quy tắc", "Chỉ chạy trên các máy chủ có vỏ màu đen"], 1,
         "Lập lịch nhận thức cấu trúc mạng (Topology-Awareness) đặt các tiến trình tính toán gần nhau nhất về mặt vật lý, tối đa hóa tốc độ giao tiếp phân tán.", "Day 20 - Slide: Topology-Aware Pod Scheduling"),
        ("Slurm Fair-Share Priority Algorithm", "Thuật toán 'Fair-Share' trong Slurm tính toán độ ưu tiên của một Job trong hàng đợi dựa trên những yếu tố lịch sử nào?",
         ["Dựa trên độ tuổi của người dùng", "Dựa trên Hạn ngạch được cấp (Allocated Target Share) so sánh với Mức tài nguyên thực tế đã tiêu thụ trong quá khứ (Historical Usage Decay): Người dùng tiêu thụ ít hơn hạn ngạch sẽ được ưu tiên chạy trước", "Dựa trên số lượng ký tự trong tên Job", "Dựa trên thời gian nộp bài thi"], 1,
         "Fair-Share đảm bảo sự công bằng dài hạn giữa các nhóm nghiên cứu, ngăn chặn hiện tượng một nhóm chiếm dụng toàn bộ cụm máy tính liên tục nhiều tuần.", "Day 20 - Slide: Slurm Fair-Share Algorithm & Priority Calculation"),
        ("Multi-Instance GPU (MIG) Slicing in K8s", "Công nghệ NVIDIA MIG (Multi-Instance GPU trên A100/H100) được tích hợp vào Kubernetes cho phép làm gì?",
         ["Biến GPU thành CPU", "Chia nhỏ một GPU vật lý thành tối đa 7 thực thể GPU độc lập hoàn toàn (MIG Instances) có bộ nhớ VRAM, băng thông và lõi tính toán được cô lập phần cứng tuyệt đối, cho phép phục vụ an toàn cho 7 Pods khác nhau", "Tăng kích thước GPU lên gấp 7 lần", "Chỉ cho phép chạy 1 ứng dụng duy nhất"], 1,
         "NVIDIA MIG cho phép chia sẻ GPU vật lý an toàn tuyệt đối với ranh giới phần cứng cô lập, tối ưu hóa chi phí cho các tác vụ suy luận nhẹ.", "Day 20 - Slide: NVIDIA Multi-Instance GPU (MIG) in Kubernetes"),
        ("Dynamic Resource Allocation (DRA) in Kubernetes", "Tính năng 'Dynamic Resource Allocation' (DRA) trong các phiên bản Kubernetes mới cải tiến so với Device Plugin ở điểm nào?",
         ["DRA làm cho container chạy chậm hơn", "Cho phép khai báo và cấp phát tài nguyên phần cứng tùy biến phức tạp (như Yêu cầu 4 GPU kết nối NVLink trực tiếp với nhau, hoặc Gán kèm Card mạng RoCEv2 cụ thể) với cấu trúc linh hoạt hơn nhiều so với bộ đếm số nguyên cứng nhắc", "DRA chỉ chạy được trên hệ điều hành Windows", "Không có sự khác biệt nào"], 1,
         "DRA mở ra khả năng mô tả và cấp phát các cấu hình phần cứng AI chuyên sâu (Topology, NVLink Fabric) theo cách khai báo chuẩn mực Cloud-Native.", "Day 20 - Slide: K8s Dynamic Resource Allocation (DRA)"),
        ("Slurm Prolog and Epilog Scripts", "Kịch bản 'Prolog' (Chạy trước khi Job bắt đầu) và 'Epilog' (Chạy sau khi Job kết thúc) trong Slurm thường được quản trị viên dùng để làm gì?",
         ["Để gửi tin nhắn chúc mừng", "Prolog: Kiểm tra sức khỏe GPU, dọn dẹp bộ nhớ tạm và nạp driver; Epilog: Thu dọn các tiến trình rác còn sót lại, xóa dữ liệu nhạy cảm trong `/tmp` và thiết lập lại trạng thái GPU về mặc định", "Để in báo cáo tài chính", "Để tắt máy chủ"], 1,
         "Prolog và Epilog là các chốt chặn vệ sinh tự động đảm bảo môi trường máy chủ luôn sạch sẽ và sẵn sàng trước và sau mỗi phiên tính toán của người dùng.", "Day 20 - Slide: Slurm Prolog and Epilog Maintenance Workflows"),
        ("KubeRay Autoscaling Ray Clusters", "Cơ chế Tự động Co giãn (Autoscaler) của KubeRay Operator trong Kubernetes phản ứng với khối lượng công việc AI như thế nào?",
         ["Tự động co giãn theo số lượng file mã nguồn", "Theo dõi hàng đợi tác vụ của Ray: Tự động khởi chạy thêm các Worker Pods (kèm GPU tương ứng) khi có nhiều tác vụ suy luận/huấn luyện cần xử lý, và tự động tiêu hủy các Worker nhàn rỗi để tiết kiệm chi phí", "Tắt toàn bộ cụm khi không có kết nối internet", "Chỉ chạy ở một kích thước cố định"], 1,
         "KubeRay Autoscaler tự động co giãn số lượng worker theo nhu cầu tính toán thực tế của các tác vụ Ray, tối ưu hóa tối đa chi phí hạ tầng đám mây.", "Day 20 - Slide: KubeRay Autoscaling & Dynamic Worker Pools"),
        ("K8s Horizontal Pod Autoscaler (HPA) with Prometheus Adapter", "Để cấu hình HPA co giãn số lượng Pods phục vụ LLM dựa trên chỉ số 'Độ sâu Hàng đợi Request' (Request Queue Depth) từ vLLM, quy trình tích hợp gồm những bước nào?",
         ["Chỉ cần dùng CPU Utilization mặc định", "vLLM phát metric `vllm:num_requests_waiting` -> Prometheus thu thập metric -> Prometheus Adapter chuyển đổi thành K8s Custom Metric API -> HPA đọc custom metric và tự động tăng số lượng Pods khi queue depth vượt ngưỡng quy định", "Bắt người dùng tự cấu hình HPA bằng tay", "Tắt toàn bộ hệ thống HPA"], 1,
         "Custom Metrics HPA phản ánh chính xác tải hàng đợi của dịch vụ LLM, kích hoạt mở rộng container trước khi người dùng cảm nhận thấy sự chậm trễ.", "Day 20 - Slide: Custom Metrics Autoscaling with Prometheus Adapter"),
        ("Slurm Job Preemption & Checkpointing", "Cơ chế 'Job Preemption' (Thu hồi quyền ưu tiên) trong Slurm xử lý tác vụ có độ ưu tiên thấp đang chạy như thế nào khi có Job khẩn cấp xuất hiện?",
         ["Tắt nguồn máy chủ ngay lập tức", "Gửi tín hiệu cảnh báo (SIGUSR1 / SIGTERM) cho Job đang chạy để nó lưu Checkpoint trạng thái dở dang vào đĩa trong 60 giây -> Tạm dừng hoặc hủy Job đó để nhường GPU cho Job khẩn cấp -> Tự động đưa Job cũ trở lại hàng đợi để chạy tiếp sau đó", "Xóa vĩnh viễn dữ liệu của Job đang chạy", "Từ chối Job khẩn cấp"], 1,
         "Preemption kết hợp Graceful Checkpointing tối đa hóa hiệu suất sử dụng cụm máy chủ trong khi đảm bảo các tác vụ khẩn cấp luôn được phục vụ tức thời.", "Day 20 - Slide: Slurm Job Preemption & Graceful Checkpointing"),
        ("Kubernetes Pod Eviction under Node NotReady", "Khi một Worker Node chứa 8 GPU bị mất liên lạc (Node NotReady do đứt cáp mạng), Kubernetes Controller Manager xử lý các Pods trên node đó như thế nào?",
         ["Chờ 10 năm mới xử lý", "Sau khoảng thời gian `pod-eviction-timeout` (mặc định ~5 phút), K8s đánh dấu các Pods là `Terminating` và tự động lập lịch khởi chạy các Pods mới thay thế trên một Worker Node khỏe mạnh khác trong cụm", "Tự động xóa toàn bộ cụm máy tính", "Không làm gì cả"], 1,
         "Automated Pod Eviction đảm bảo các dịch vụ AI tự động phục hồi trên các nút phần cứng khỏe mạnh khác khi xảy ra thảm họa phần cứng cục bộ.", "Day 20 - Slide: K8s Node Lifecycle & Automated Pod Eviction"),
        ("Slurm Array Jobs for Hyperparameter Tuning", "Tính năng 'Array Jobs' (`#SBATCH --array=1-100`) trong Slurm mang lại sự tiện lợi gì khi thực hiện Tinh chỉnh Siêu tham số (Hyperparameter Sweeps)?",
         ["Chạy 100 dòng code cùng lúc trên 1 GPU", "Cho phép gửi đồng thời 100 tác vụ độc lập chỉ bằng một file kịch bản duy nhất; mỗi tác vụ con nhận một chỉ số `$SLURM_ARRAY_TASK_ID` tương ứng để tự động đọc một bộ siêu tham số khác nhau từ danh sách cấu hình", "Tự động sửa lỗi siêu tham số", "Chỉ dùng cho các bài toán số học đơn giản"], 1,
         "Array Jobs là công cụ đắc lực tự động hóa việc chạy song song hàng trăm thử nghiệm siêu tham số trên cụm siêu máy tính một cách tinh gọn.", "Day 20 - Slide: Slurm Array Jobs for Hyperparameter Sweeps"),
        ("Kubernetes Pod Disruption Budgets (PDB)", "Tài nguyên 'PodDisruptionBudget' (PDB) trong Kubernetes bảo vệ các dịch vụ AI Phục vụ Trực tuyến trong quá trình nâng cấp cụm (Cluster Maintenance) như thế nào?",
         ["Cấm quản trị viên nâng cấp hệ thống", "Quy định số lượng Pods tối thiểu BẮT BUỘC PHẢI LUÔN HOẠT ĐỘNG (ví dụ: `minAvailable: 80%`): Hệ thống chỉ được phép bảo trì/khởi động lại từng node một khi đã đảm bảo đủ số lượng Pods phục vụ khách hàng", "Tự động tắt toàn bộ dịch vụ khi nâng cấp", "Xóa toàn bộ các Pods cũ"], 1,
         "PDB thiết lập rào chắn an toàn ngăn chặn việc bảo trì hạ tầng làm gián đoạn tính sẵn sàng của các dịch vụ trực tuyến quan trọng.", "Day 20 - Slide: Pod Disruption Budgets (PDB) for AI Services"),
        ("Slurm Heterogeneous Jobs (HetJobs)", "Tính năng 'Heterogeneous Jobs' (HetJobs) trong Slurm được thiết kế để giải quyết bài toán nào?",
         ["Chạy trên các máy chủ có hệ điều hành khác nhau", "Cho phép một Job duy nhất yêu cầu đồng thời nhiều nhóm tài nguyên phần cứng hoàn toàn khác nhau trong cùng một kịch bản (ví dụ: Nhóm 1 cần 4 nodes CPU mạnh để tiền xử lý dữ liệu, Nhóm 2 cần 16 nodes GPU H100 để huấn luyện mô hình)", "Tự động chuyển đổi ngôn ngữ lập trình", "Không có tác dụng gì"], 1,
         "HetJobs hỗ trợ mô hình hóa các quy trình tính toán đa giai đoạn phức tạp với các yêu cầu phần cứng không đồng nhất trong một tác vụ thống nhất.", "Day 20 - Slide: Slurm Heterogeneous Jobs (HetJobs)"),
        ("K8s Storage Integration: CSI Drivers", "Container Storage Interface (CSI Driver) trong Kubernetes cho phép cụm AI kết nối với hệ thống lưu trữ phân tán hiệu năng cao như thế nào?",
         ["Chỉ cho phép đọc đĩa mềm", "Chuẩn hóa giao diện cắm ghép: Cho phép Kubernetes tự động gắn kết (Mount) các phân vùng lưu trữ phân tán (như Lustre, Ceph, AWS FSx for Lustre, GPFS) trực tiếp vào không gian thư mục của Pods với quyền truy cập đồng thời ReadWriteMany (RWX)", "Tự động nén toàn bộ dữ liệu", "Xóa dữ liệu sau mỗi lần đọc"], 1,
         "CSI Drivers chuẩn hóa việc tích hợp các hệ thống tệp tin song song hiệu năng cao vào container một cách tự động và an toàn.", "Day 20 - Slide: Kubernetes CSI Drivers for High-Performance AI Storage"),
        ("Slurm Accounting & Sacct Tool", "Công cụ dòng lệnh `sacct` trong Slurm cung cấp những thông tin lịch sử quan trọng nào sau khi một Job kết thúc?",
         ["Cung cấp mật khẩu của người dùng", "Báo cáo chi tiết về Thời gian chạy thực tế (Elapsed Time), Trạng thái kết thúc (COMPLETED / FAILED / OUT_OF_MEMORY), Mức tiêu thụ RAM đỉnh (MaxRSS) và Hiệu suất sử dụng CPU/GPU của Job", "Cung cấp thời tiết ngày hôm đó", "In ra toàn bộ mã nguồn của chương trình"], 1,
         "`sacct` là công cụ chẩn đoán cốt lõi giúp lập trình viên phân tích nguyên nhân thất bại và tối ưu hóa việc phân bổ tài nguyên cho các lần chạy sau.", "Day 20 - Slide: Slurm Accounting & Resource Profiling with sacct"),
        ("Kubernetes Security: Pod Security Standards (PSS)", "Tiêu chuẩn 'Pod Security Standards' (mức Restricted) trong Kubernetes bảo vệ cụm AI khỏi các rủi ro bảo mật nào?",
         ["Cấm người dùng gõ lệnh sai cú pháp", "Bắt buộc container phải chạy với tài khoản Non-Root, cấm leo thang đặc quyền (Privilege Escalation), khóa quyền truy cập trực tiếp vào Host Network/IPC trừ khi được cấp phép đặc biệt, ngăn ngừa nguy cơ thoát container (Container Breakout)", "Tự động mã hóa màn hình máy tính", "Chỉ cho phép chạy các file văn bản"], 1,
         "Pod Security Standards thực thi các chính sách bảo mật vùng cách ly nghiêm ngặt, bảo vệ hạ tầng máy chủ mẹ khỏi các cuộc tấn công khai thác lỗ hổng container.", "Day 20 - Slide: K8s Pod Security Standards for AI Workloads"),
        ("Slurm Epilog Slurmctld vs Epilog", "Sự khác biệt giữa 'Epilog' (chạy trên Worker Node) và 'EpilogSlurmctld' (chạy trên Máy chủ Quản lý Trung tâm Slurmctld) trong Slurm là gì?",
         ["Không có sự khác biệt nào", "`Epilog` chạy trực tiếp trên các máy chủ tính toán (Compute Nodes) với quyền root để dọn dẹp phần cứng; `EpilogSlurmctld` chạy trên máy chủ điều khiển trung tâm để cập nhật trạng thái cơ sở dữ liệu kế toán, gửi webhook thông báo hoặc kích hoạt Job tiếp theo", "`Epilog` chỉ chạy vào ban ngày", "`EpilogSlurmctld` dùng để in file PDF"], 1,
         "Phân tách rõ ràng giữa dọn dẹp tài nguyên vật lý cục bộ và điều phối trạng thái toàn cục giúp hệ thống Slurm duy trì tính toàn vẹn và độ tin cậy cao.", "Day 20 - Slide: Slurm Centralized vs Distributed Epilog Architecture")
    ]

    d20_hard = [
        ("Enterprise Unified Hybrid Orchestration Architecture (Slurm + Kubernetes)", "Thiết kế Bản thiết kế Kiến trúc Điều phối Hỗn hợp Thống nhất (Master Hybrid AI Orchestration Blueprint) cho một Viện Nghiên cứu Trí tuệ Nhân tạo Quốc gia sở hữu 10,000 GPUs H100. Làm thế nào để điều phối đồng thời Cụm Slurm (chuyên Huấn luyện Siêu Mô hình Foundation) và Cụm Kubernetes (chuyên Phục vụ Suy luận Trực tuyến & Data Pipelines) chia sẻ chung một Nguồn Tài nguyên Phần cứng Động (Dynamic Resource Re-allocation)?",
         ["Chia đôi máy tính bằng bức tường gạch vật lý không cho dùng chung", "Triển khai Kiến trúc Điều phối Hai Tầng Động (Two-Tier Dynamic Hardware Partitioning & Elastic Provisioning): 1. Tầng Hạ tầng Trần (Bare-Metal Base with Slurm Workload Manager) quản lý toàn bộ 10,000 GPUs với băng thông InfiniBand NDR tối đa cho các Job Pre-training lớn; 2. Tầng Co giãn Đám mây K8s (Virtual Kubernetes Cluster on Demand via Kube-on-Slurm / Slurm-K8s Bridge): Khi có nhu cầu mở rộng dịch vụ suy luận trực tuyến trong giờ cao điểm, hệ thống tự động gửi các Slurm Jobs khởi chạy các K8s Worker Nodes ảo hóa siêu nhẹ (MicroVMs với GPU Passthrough); 3. Khi tải suy luận giảm vào ban đêm, K8s tự động thu hồi Pods và trả lại tài nguyên GPU cho hàng đợi huấn luyện Slurm; 4. Hệ thống Lưu trữ Song song WEKA/Lustre chia sẻ chung cho cả 2 môi trường", "Chỉ sử dụng duy nhất một môi trường và cấm môi trường còn lại", "Tắt toàn bộ máy chủ khi chuyển đổi giữa 2 hệ thống"], 1,
         "Kiến trúc điều phối lai động giải quyết hoàn hảo bài toán xung đột giữa tính linh hoạt của Cloud-Native Kubernetes và hiệu năng cực hạn của HPC Slurm, tối đa hóa 100% hiệu suất đầu tư phần cứng.", "Day 20 - Slide: Master Hybrid Slurm-Kubernetes AI Architecture"),
        ("Mathematical Formulation of Fair-Share Scheduling under Multi-Dimensional Decay", "Phân tích công thức toán học tính toán Hệ số Ưu tiên Fair-Share ($P_{\\text{fairshare}}$) trong Slurm và cơ chế Suy giảm Lũy thừa Lịch sử (Exponential Historical Usage Decay)?",
         ["$P_{\\text{fairshare}} = 1 / \\text{Tuổi của người dùng}$", "Độ ưu tiên Fair-Share $P_{\\text{fairshare}} = 2^{-\\frac{U}{S}}$ (trong đó $S$ là Tỉ lệ Hạn ngạch Chuẩn của nhóm người dùng, $U$ là Mức sử dụng chuẩn hóa thực tế). Mức sử dụng $U(t)$ được cập nhật liên tục theo phương trình vi phân suy giảm thời gian: $U(t) = U_0 e^{-\\frac{\\Delta t}{\\tau}} + \\text{NewUsage}$, với chu kỳ bán rã $\\tau$ (Half-life, ví dụ: 7 ngày) giúp giảm dần trọng số sử dụng của các tác vụ cũ trong quá khứ", "$P_{\\text{fairshare}}$ là một hằng số ngẫu nhiên", "Độ ưu tiên bằng 0 nếu người dùng không nộp tiền"], 1,
         "Phương trình suy giảm lũy thừa thời gian cân bằng hoàn hảo giữa việc bù đắp cho các nhóm bị thiếu tài nguyên trong thời gian dài và việc không phạt vĩnh viễn các nhóm vừa chạy tác vụ lớn trong quá khứ.", "Day 20 - Slide: Mathematical Formulation of Slurm Fair-Share Priority"),
        ("Kubernetes Gang Scheduling under Network Topology Graph Constraints", "Khi điều phối một Job huấn luyện 512 GPUs phân tán trên cụm Kubernetes, thiết kế Thuật toán Lập lịch Đồ thị Ràng buộc Tôpô (Topology-Constrained Gang Scheduling Algorithm in Volcano) đảm bảo 100% các Pods cùng một Gang được gán vào cùng một Nhánh Cáp Switch Spine (Zero Cross-Spine Traffic)?",
         ["Lập lịch ngẫu nhiên từng Pod một", "Mô hình hóa Hạ tầng Mạng dưới dạng Đồ thị Phân cấp (Tree Network Topology Graph): 1. Thuật toán duyệt cây từ tầng dưới lên (Bottom-Up Tree Search) tìm kiếm Cụm Switch Leaf/Spine nhỏ nhất có đủ 64 Worker Nodes (512 GPUs) còn rỗng; 2. Áp dụng Khóa Nguyên tử (Atomic Gang Reservation): Giữ chỗ đồng thời toàn bộ 64 vị trí trên cây tôpô; 3. Nếu không tìm thấy cây con thỏa mãn điều kiện cô lập mạng, Job sẽ tiếp tục xếp hàng chờ (Queued) thay vì bị phân tán rải rác trên nhiều Spine Switch gây nghẽn mạng toàn cụm", "Chạy các Pods trên bất kỳ máy chủ nào còn trống", "Tắt toàn bộ hệ thống mạng Spine"], 1,
         "Lập lịch ràng buộc đồ thị tôpô kết hợp đặt chỗ nguyên tử triệt tiêu hoàn toàn lưu lượng giao tiếp xuyên nhánh cáp trục chính, bảo vệ băng thông và tính ổn định tối đa cho Job huấn luyện.", "Day 20 - Slide: Topology-Constrained Gang Scheduling Algorithms in Volcano"),
        ("Automated GPU Failure Eviction & Zero-Loss Job Resumption", "Trong một Job huấn luyện phân tán 1,024 GPUs trên Kubernetes kéo dài 30 ngày, một GPU trên Node 45 bị lỗi bộ nhớ cứng (Uncorrectable ECC Error). Thiết kế Kiến trúc Tự Phục hồi & Tái Khởi động Tức thời (Sub-Minute Automated Fault-Tolerance Controller) diễn ra như thế nào?",
         ["Hủy bỏ toàn bộ quá trình huấn luyện và bắt đầu lại từ đầu", "Quy trình Tự Phục hồi Tự động 5 Bước: 1. NVIDIA GPU Operator/DCGM phát hiện lỗi Fatal ECC và phát sự kiện `NodeUnhealthy`; 2. K8s Controller lập tức gửi tín hiệu SIGTERM cho Job, kích hoạt tiến trình lưu Checkpoint khẩn cấp vào NVMe Burst Buffer trong 10 giây; 3. Volcano Scheduler tự động rút Node 45 khỏi cụm (Cordon & Drain), cấp phát Node dự phòng khỏe mạnh (Hot-Spare Node); 4. Tự động khởi chạy lại Gang Pods mới; 5. TorchElastic tải Checkpoint gần nhất và tiếp tục huấn luyện trong < 45 giây", "Khởi động lại toàn bộ trung tâm dữ liệu", "Bỏ qua lỗi và tiếp tục tính toán với dữ liệu hỏng"], 1,
         "Cơ chế tự động cô lập nút lỗi kết hợp lưu checkpoint khẩn cấp và cấp phát nút dự phòng nóng đảm bảo các chiến dịch huấn luyện quy mô lớn vận hành liên tục 24/7 mà không bị gián đoạn bởi sự cố phần cứng.", "Day 20 - Slide: Automated GPU Node Eviction & Resilient Job Resumption"),
        ("Multi-Tenant GPU Quota Enforcement with Hierarchical Cohorts in Kueue", "Một tập đoàn AI có 4 phòng ban cùng chia sẻ cụm 2,000 GPUs. Thiết kế Cơ chế Phân bổ Hạn ngạch Phân cấp (Hierarchical Cohort Resource Quotas & Borrowing Mechanics in Kueue) đảm bảo: Phòng ban luôn có số GPU tối thiểu cam kết, nhưng được phép 'Mượn tạm' GPU nhàn rỗi của phòng ban khác và tự động trả lại (Reclaim) khi có nhu cầu?",
         ["Khóa cứng mỗi phòng ban đúng 500 GPU vĩnh viễn không cho chia sẻ", "Xây dựng Cây Hạn ngạch Phân cấp (Hierarchical Resource Cohort Tree in Kueue): Định nghĩa `Guaranteed Quota` (Hạn ngạch cam kết bảo đảm) và `Borrowing Limit` (Giới hạn mượn tối đa) cho từng phòng ban trong cùng một Cohort; Khi Phòng A không sử dụng hết 500 GPU, Phòng B được phép mượn tạm để chạy tác vụ; Khi Phòng A nộp Job mới, Kueue lập tức kích hoạt cơ chế Thu hồi Quyền ưu tiên (Graceful Workload Preemption) yêu cầu Phòng B trả lại tài nguyên trong 60 giây", "Cho phép các phòng ban tranh chấp tự do không có luật lệ", "Chỉ cấp GPU cho phòng ban có giám đốc lớn nhất"], 1,
         "Hierarchical Cohort Quotas và cơ chế mượn/trả tài nguyên tự động tối ưu hóa 100% hiệu suất sử dụng GPU của toàn tập đoàn trong khi đảm bảo tuyệt đối cam kết SLA cho từng phòng ban.", "Day 20 - Slide: Hierarchical Quota Management and Workload Preemption in Kueue"),
        ("Heterogeneous GPU Slicing Architecture (Bare-Metal + MIG + Time-Slicing)", "Thiết kế một Bản thiết kế Phân mảnh Tài nguyên GPU Đa Cấp độ (Multi-Tier GPU Slicing Matrix) trên Kubernetes phục vụ đồng thời 3 loại tải: 1. Deep Learning Training (Cần Full GPU H100); 2. Production LLM Serving (Cần MIG 3g.40gb); 3. Development / Debugging (Cần Time-Slicing 0.1 GPU)?",
         ["Chỉ cho phép chạy chế độ Full GPU cho tất cả mọi người", "Triển khai Ma trận Phân mảnh GPU 3 Phân vùng: 1. Dedicated GPU Node Pool (Chạy Full Bare-Metal H100 GPU không phân mảnh cho Training); 2. MIG-Enabled Node Pool (Cấu hình GPU Operator tự động chia H100 thành các lát cắt phần cứng `nvidia.com/mig-3g.40gb` với VRAM và SMs cô lập cho Production Inference); 3. Time-Slicing Node Pool (Cấu hình `nvidia-container-toolkit` chia sẻ thời gian ảo hóa cho các môi trường Dev/Jupyter Notebooks), tối đa hóa 100% hiệu quả kinh tế", "Cấm các lập trình viên không được debug trên cụm", "Tắt toàn bộ các tính năng phân mảnh"], 1,
         "Phân tầng cụm GPU theo các chế độ phân mảnh chuyên biệt (Bare-metal, MIG, Time-slicing) đáp ứng hoàn hảo yêu cầu kỹ thuật đặc thù của từng loại tải với chi phí tối ưu nhất.", "Day 20 - Slide: Enterprise Multi-Tier GPU Slicing Architecture"),
        ("Slurm High-Throughput Burst Scheduling Optimization", "Khi cụm Slurm phải tiếp nhận 100,000 Jobs ngắn hạn mỗi giờ từ hệ thống Đánh giá Mô hình Tự động (Automated Eval Pipeline), làm thế nào để cấu hình `slurmctld` không bị nghẽn và đạt thông lượng xử lý hàng nghìn Jobs/giây?",
         ["Cấm người dùng không được gửi nhiều Jobs", "Tối ưu hóa Cấu hình Slurmctld: 1. Kích hoạt `SchedulerParameters=sched_min_interval=1000,default_queue_depth=5000,bf_max_job_user=1000`; 2. Chuyển đổi Cơ chế Lập lịch sang Đa luồng Bất đồng bộ (Pthreads Scheduling & Backfill Scheduler Tuning); 3. Cấu hình Cụm Cơ sở dữ liệu SlurmDBD trên SSD NVMe với Connection Pooling; 4. Gom nhóm các Jobs nhỏ thành Slurm Job Arrays để giảm tải cho bộ nhớ tiến trình điều khiển", "Tắt toàn bộ hệ thống Slurm", "Khởi động lại máy chủ mỗi 10 phút"], 1,
         "Tinh chỉnh các tham số lập lịch luồng phụ và tối ưu hóa cơ sở dữ liệu SlurmDBD cho phép hệ thống Slurm xử lý mượt mà các đợt bùng nổ hàng trăm nghìn tác vụ vi mô.", "Day 20 - Slide: Slurm High-Throughput Scheduling Engine Optimization"),
        ("Kubernetes CoreDNS & Service Discovery Scaling under Massive Pod Churn", "Khi một cụm Kubernetes thường xuyên khởi tạo và tiêu hủy hàng chục nghìn Pods AI huấn luyện mỗi ngày, hệ thống phân giải tên miền nội bộ (CoreDNS) bị quá tải sập mạng. Kiến trúc Phân giải Tên miền Phân tán nào giải quyết sự cố này?",
         ["Tắt hoàn toàn hệ thống DNS nội bộ", "Triển khai Kiến trúc DNS Phân tán Cục bộ (NodeLocal DNSCache): Cài đặt một DaemonSet DNS Caching nhẹ chạy trực tiếp trên từng Worker Node lắng nghe IP cục bộ; 99% các truy vấn DNS của Pods được phục vụ tức thì từ bộ đệm RAM cục bộ của Node, triệt tiêu 100% tải tập trung lên cụm CoreDNS trung tâm", "Bắt mỗi Pod phải tự nhớ địa chỉ IP của các Pods khác", "Cài đặt lại toàn bộ hệ điều hành Kubernetes"], 1,
         "NodeLocal DNSCache phân tán việc phân giải tên miền xuống từng máy chủ vật lý, loại bỏ điểm nghẽn tập trung và bảo vệ tính ổn định của cụm khi có biến động container quy mô lớn.", "Day 20 - Slide: Scaling K8s Service Discovery with NodeLocal DNSCache"),
        ("Slurm Multi-Cluster Federation & Cross-Site Bursting", "Khi một trường Đại học sở hữu 3 cụm Siêu máy tính Slurm đặt tại 3 cơ sở địa lý khác nhau, kiến trúc 'Slurm Multi-Cluster Federation' điều phối công việc xuyên cụm như thế nào?",
         ["Yêu cầu người dùng phải tự đăng nhập vào từng cụm riêng lẻ", "Thiết lập Liên minh Cụm Slurm Tập trung (Slurm Federated Cluster Architecture): Sử dụng chung một Cơ sở dữ liệu SlurmDBD duy nhất đồng bộ hóa trạng thái; Khi người dùng nộp Job tại Cụm A nhưng Cụm A đang đầy tải, Federation Controller tự động phân tích hàng đợi và chuyển tiếp (Burst/Route) Job sang Cụm B hoặc C đang nhàn rỗi một cách trong suốt", "Tắt 2 cụm và chỉ giữ lại 1 cụm duy nhất", "Gửi dữ liệu qua bưu điện giữa các cụm"], 1,
         "Slurm Federation liên kết các siêu máy tính phân tán thành một lưới điện toán hợp nhất, tối ưu hóa việc chia sẻ tài nguyên và cân bằng tải trên toàn quốc gia.", "Day 20 - Slide: Slurm Multi-Cluster Federation Architecture"),
        ("K8s Ephemeral Storage & HugePages Management for AI Pods", "Tại sao việc cấu hình `hugepages-2Mi` / `hugepages-1Gi` và Quản lý Bộ nhớ Tạm thời (Ephemeral Storage Limits) trong Pod Spec lại là yêu cầu sống còn cho các tác vụ Huấn luyện AI?",
         ["Để làm cho Pod trông chuyên nghiệp hơn", "1. HugePages khóa các trang bộ nhớ kích thước lớn (2MB/1GB) trong RAM vật lý, loại bỏ chi phí TLB Cache Misses và tăng 15-20% thông lượng I/O của mô hình PyTorch; 2. Ephemeral Storage Limits ngăn chặn việc một Pod ghi tràn ổ đĩa chứa `/tmp` làm sập toàn bộ hệ điều hành của Worker Node mẹ", "HugePages chỉ dùng để lưu trữ file ảnh", "Không có tác dụng gì đối với hiệu năng"], 1,
         "HugePages tối ưu hóa bảng trang nhớ phần cứng trong khi Ephemeral Limits bảo vệ tính toàn vẹn của máy chủ mẹ trước các sự cố rò rỉ dữ liệu tạm.", "Day 20 - Slide: HugePages and Ephemeral Storage Governance in AI Pods"),
        ("Slurm Job Energy Accounting & Carbon-Aware Scheduling", "Làm thế nào để hệ thống Slurm tự động điều phối các tác vụ tính toán khổng lồ theo 'Chỉ số Phát thải Carbon' (Carbon-Aware AI Scheduling) để giảm thiểu tác động môi trường?",
         ["Tắt toàn bộ máy tính", "Tích hợp Slurm với Dữ liệu Lưới Điện Thời gian thực (Green-Grid API): Hệ thống tự động theo dõi Tỉ lệ Năng lượng Tái tạo (Điện gió, Điện mặt trời) trên lưới điện quốc gia; Tự động đẩy nhanh các Job huấn luyện lớn vào các khung giờ năng lượng xanh dồi dào và hạ xung nhịp GPU (DVFS) vào các khung giờ điện than/nhiệt điện", "Chỉ cho phép chạy AI vào mùa xuân", "Không thể đo lường được lượng carbon"], 1,
         "Carbon-Aware Scheduling kết hợp điều phối thông minh với dữ liệu lưới điện thời gian thực, đưa các trung tâm dữ liệu AI phát triển theo hướng bền vững và thân thiện môi trường.", "Day 20 - Slide: Carbon-Aware & Green Energy HPC Scheduling"),
        ("Comprehensive Cluster Observability: Prometheus + Grafana + Slurm/K8s Exporters", "Thiết kế một Dashboard Giám sát Toàn diện Đa Tầng (Full-Stack Cluster Observability Dashboard) tích hợp đồng thời dữ liệu từ Slurm, Kubernetes và NVIDIA GPUs. Những đồ thị tương quan chéo nào là chỉ dấu cảnh báo sớm sự suy thoái hiệu năng cụm?",
         ["Chỉ hiển thị logo của công ty", "1. Tương quan giữa Tỉ lệ Sử dụng GPU (GPU Utilization %) và Băng thông Giao tiếp Mạng (InfiniBand Throughput GB/s) để phát hiện nghẽn truyền thông; 2. Biểu đồ Thời gian Chờ Hàng đợi vs Hạn ngạch Người dùng (Queue Wait Time vs Fair-share Index); 3. Bản đồ Nhiệt Độ và Sụt áp Rack GPU (Thermal & Power Headroom Map); 4. Tỉ lệ Lỗi Bộ nhớ ECC Xuyên Cụm", "Chỉ hiển thị đồng hồ xem giờ", "Đếm số lượng kỹ sư đang online"], 1,
         "Bảng điều khiển giám sát tương quan chéo đa tầng cung cấp cái nhìn toàn cảnh về sức khỏe phần cứng, hiệu quả lập lịch và các điểm nghẽn hiệu năng của toàn bộ hạ tầng siêu máy tính.", "Day 20 - Slide: Full-Stack AI Cluster Observability Architecture")
    ]
    add_day("Track 2: Infrastructure", "Day 20", "Orchestration with Kubernetes & Slurm", d20_easy, d20_med, d20_hard)

    return questions
